"use strict";

var React = require("react");

function useSharedValue(initial) {
  return React.useRef({ value: initial }).current;
}

function useAnimatedStyle(updater, dependencies) {
  if (!dependencies && !updater.__workletHash) {
    throw new Error(
      "[Reanimated] `useAnimatedStyle` was used without a dependency array or Babel plugin.",
    );
  }
  return { initial: updater(), inputs: Object.keys(updater.__closure) };
}

exports.useSharedValue = useSharedValue;
exports.useAnimatedStyle = useAnimatedStyle;
